use std::future::Future;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::task::{Context, Waker};
use tokio::sync::{Mutex, OnceCell, RwLock, Semaphore, mpsc};
use tracing::field::{Field, Visit};
use tracing::span::{Attributes, Id, Record};
use tracing::{Event, Metadata, Subscriber};

// Ignore zero-capacity telemetry emitted before the fast path takes permits.
struct PositiveAcquisition(bool);

impl Visit for PositiveAcquisition {
    fn record_u64(&mut self, field: &Field, value: u64) {
        if field.name() == "permits_obtained" && value > 0 {
            self.0 = true;
        }
    }

    fn record_debug(&mut self, _: &Field, _: &dyn std::fmt::Debug) {}
}

struct PanicSubscriber(Arc<AtomicBool>);

impl Subscriber for PanicSubscriber {
    fn enabled(&self, _: &Metadata<'_>) -> bool {
        true
    }

    fn new_span(&self, _: &Attributes<'_>) -> Id {
        Id::from_u64(1)
    }

    fn record(&self, _: &Id, _: &Record<'_>) {}

    fn record_follows_from(&self, _: &Id, _: &Id) {}

    fn event(&self, event: &Event<'_>) {
        let mut acquired = PositiveAcquisition(false);
        event.record(&mut acquired);
        if acquired.0 && self.0.swap(false, Ordering::Relaxed) {
            panic!("one recoverable telemetry panic after acquiring permits");
        }
    }

    fn enter(&self, _: &Id) {}

    fn exit(&self, _: &Id) {}
}

fn main() {
    let control = std::env::args().any(|arg| arg == "--control");
    let armed = Arc::new(AtomicBool::new(false));
    let _subscriber = tracing::subscriber::set_default(PanicSubscriber(armed.clone()));
    let mut cx = Context::from_waker(Waker::noop());

    // Each acquisition starts uncontended; unwind must release its capacity.
    let semaphore = Semaphore::new(1);
    armed.store(!control, Ordering::Relaxed);
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut acquire = Box::pin(semaphore.acquire());
        assert!(acquire.as_mut().poll(&mut cx).is_ready());
    }));
    assert_eq!(result.is_err(), !control);
    assert_eq!(semaphore.available_permits(), usize::from(control));
    eprintln!(
        "semaphore permits after unwind: {}",
        semaphore.available_permits()
    );

    let mutex = Mutex::new(7);
    armed.store(!control, Ordering::Relaxed);
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut acquire = Box::pin(mutex.lock());
        assert!(acquire.as_mut().poll(&mut cx).is_ready());
    }));
    assert_eq!(result.is_err(), !control);
    assert_eq!(mutex.try_lock().is_ok(), control);
    eprintln!("mutex can be acquired after unwind: {control}");

    let rwlock = RwLock::new(7);
    armed.store(!control, Ordering::Relaxed);
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut acquire = Box::pin(rwlock.write());
        assert!(acquire.as_mut().poll(&mut cx).is_ready());
    }));
    assert_eq!(result.is_err(), !control);
    assert_eq!(rwlock.try_write().is_ok(), control);
    assert_eq!(rwlock.try_read().is_ok(), control);
    eprintln!("rwlock can be read or written after unwind: {control}");

    // Initialization that never starts must leave the cell available for retry.
    let cell = OnceCell::new();
    armed.store(!control, Ordering::Relaxed);
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut acquire = Box::pin(cell.get_or_init(|| async { 7 }));
        assert!(acquire.as_mut().poll(&mut cx).is_ready());
    }));
    assert_eq!(result.is_err(), !control);
    assert_eq!(cell.initialized(), control);
    let mut retry = Box::pin(cell.get_or_init(|| async { 8 }));
    assert_eq!(retry.as_mut().poll(&mut cx).is_ready(), control);
    eprintln!("OnceCell can complete initialization after unwind: {control}");

    let (sender, _receiver) = mpsc::channel::<()>(1);
    armed.store(!control, Ordering::Relaxed);
    let result = catch_unwind(AssertUnwindSafe(|| {
        let mut acquire = Box::pin(sender.reserve());
        assert!(acquire.as_mut().poll(&mut cx).is_ready());
    }));
    assert_eq!(result.is_err(), !control);
    assert_eq!(sender.capacity(), usize::from(control));
    assert_eq!(sender.try_send(()).is_ok(), control);
    eprintln!("empty bounded MPSC channel can send after unwind: {control}");
}
